#!/bin/bash
# Test ingestion trigger script

# Your session cookie (copy the entire cookie string from browser)
COOKIE="__next_hmr_refresh_hash__=76ac3ddb70b304db73eaea9ebdc74f2721faa5cd43f7aa38; sb-mddgtexrnnlctttbcpsy-auth-token.0=base64-; sb-mddgtexrnnlctttbcpsy-auth-token.1=W5vbnltb3VzIjpmYWxzZX19"

# Trigger ingestion for all active sources
echo "Triggering ingestion for all active sources..."
echo ""

RESPONSE=$(curl -s -w "\nHTTP_STATUS:%{http_code}" -X POST "http://localhost:3000/api/admin/ingestion/run" \
  -H "Cookie: $COOKIE" \
  -H "Content-Type: application/json" \
  -d '{}')

# Extract HTTP status and body
HTTP_STATUS=$(echo "$RESPONSE" | grep "HTTP_STATUS" | cut -d: -f2)
BODY=$(echo "$RESPONSE" | sed '/HTTP_STATUS/d')

echo "HTTP Status: $HTTP_STATUS"
echo ""
echo "Response:"
echo "$BODY" | jq . 2>/dev/null || echo "$BODY"
echo ""

